impl Solution {
    pub fn stone_game_v(stone_value: Vec<i32>) -> i32 {
        let n = stone_value.len();
        if n <= 1 {
            return 0;
        }
        let mut prefix = vec![0i64; n + 1];
        for i in 0..n {
            prefix[i + 1] = prefix[i] + stone_value[i] as i64;
        }
        let mut dp = vec![vec![0i64; n]; n];
        for len in 2..=n {
            for l in 0..=n - len {
                let r = l + len - 1;
                let mut best = 0i64;
                for k in l..r {
                    let left = prefix[k + 1] - prefix[l];
                    let right = prefix[r + 1] - prefix[k + 1];
                    let score = if left < right {
                        left + dp[l][k]
                    } else if left > right {
                        right + dp[k + 1][r]
                    } else {
                        let s1 = left + dp[l][k];
                        let s2 = right + dp[k + 1][r];
                        if s1 > s2 { s1 } else { s2 }
                    };
                    if score > best {
                        best = score;
                    }
                }
                dp[l][r] = best;
            }
        }
        dp[0][n - 1] as i32
    }
}

